-- Passage rg7-story-details-inference-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('c00383b8-13bb-5211-8ef3-a1bd81924d6f', 'rg7-story-details-inference-p06', (select id from public.skills where slug = 'read-g7-story-details-inference'), null,
        '6-8', $q$Bus Fourteen$q$, $q$The same driver every morning,
gray cap, a thermos tucked beside the fare box.
She knows which stop is mine before I stand.

She waits for Mr. Liang, who walks with a cane,
and she never once looks at her watch.
When the high school kids get loud,
she only lifts her eyes to the mirror,
and the whole back row goes quiet.

On the first cold day in November,
I left my gloves behind on the seat.
The next morning they were waiting for me,
folded on the dashboard,
right where I could see them from the curb.

Today there is a new driver,
a young man who checks his map at every light.
He rolls past my stop by half a block.
Nobody on the bus says anything.
But Mr. Liang looks out the window the whole way,
and I notice I am looking too,
searching the sidewalks for a gray cap.$q$, 'draft')
